  [ ("check", encInt (checkOneCheck r))
  , ("one", encStr (checkOneOne r))
  , ("path", encList (checkOnePath r))
  , ("head", encList (checkOneHead r))
  ]

checkOneCheckL :: Lens' CheckOne (Int)
checkOneCheckL k r = (\v -> r { checkOneCheck = v }) <$> k (checkOneCheck r)
{-# INLINE checkOneCheckL #-}

checkOneOneL :: Lens' CheckOne (String)
checkOneOneL k r = (\v -> r { checkOneOne = v }) <$> k (checkOneOne r)
{-# INLINE checkOneOneL #-}

checkOnePathL :: Lens' CheckOne ([String])
checkOnePathL k r = (\v -> r { checkOnePath = v }) <$> k (checkOnePath r)
{-# INLINE checkOnePathL #-}

checkOneHeadL :: Lens' CheckOne ([String])
checkOneHeadL k r = (\v -> r { checkOneHead = v }) <$> k (checkOneHead r)
{-# INLINE checkOneHeadL #-}

-- | Mirrors the record @main@ reads and writes (bin/ade-template-check:493).
data MainRecord = MainRecord
  { mainRecordMain :: String
  , mainRecordPath :: [String]
  , mainRecordHead :: Int
  , mainRecordStatus :: [String]
  } deriving (Show, Eq)

defaultMainRecord :: MainRecord
defaultMainRecord = MainRecord
  { mainRecordMain = ""
  , mainRecordPath = []
  , mainRecordHead = 0
  , mainRecordStatus = []
  }

decodeMainRecord :: Fields -> Either String MainRecord
decodeMainRecord kv =
  MainRecord
    <$> fieldStr "main" kv
    <*> fieldList "path" kv
    <*> fieldInt "head" kv
    <*> fieldList "status" kv

encodeMainRecord :: MainRecord -> Fields
encodeMainRecord r =
  [ ("main", encStr (mainRecordMain r))
  , ("path", encList (mainRecordPath r))
  , ("head", encInt (mainRecordHead r))
  , ("status", encList (mainRecordStatus r))
  ]

mainRecordMainL :: Lens' MainRecord (String)
mainRecordMainL k r = (\v -> r { mainRecordMain = v }) <$> k (mainRecordMain r)
{-# INLINE mainRecordMainL #-}

mainRecordPathL :: Lens' MainRecord ([String])
mainRecordPathL k r = (\v -> r { mainRecordPath = v }) <$> k (mainRecordPath r)
{-# INLINE mainRecordPathL #-}

mainRecordHeadL :: Lens' MainRecord (Int)
mainRecordHeadL k r = (\v -> r { mainRecordHead = v }) <$> k (mainRecordHead r)
{-# INLINE mainRecordHeadL #-}

mainRecordStatusL :: Lens' MainRecord ([String])
mainRecordStatusL k r = (\v -> r { mainRecordStatus = v }) <$> k (mainRecordStatus r)
{-# INLINE mainRecordStatusL #-}

